var o=`0425-kottbullar`;var t=`world-0425`;var a=`SE`;var r=`northern-europe`;var i=4;var l=44;var s={en:`Köttbullar`,ua:`Шведські м'ясні кульки`};var g={en:`A traditional dish from Sweden, centered on ground beef, ground pork, yellow onion, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Швеція. Основні складники: яловичий фарш, свинячий фарш, жовта цибуля, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`ground-beef`,390,`g`],[`ground-pork`,280,`g`],[`yellow-onion`,140,`g`],[`chicken-egg`,1,`pcs`],[`breadcrumbs`,95,`g`],[`whole-cow-milk`,150,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`unsalted-butter`,65,`g`]]},{en:`After frying meatballs, whisk flour into the pan drippings, add stock and cream, and simmer into a smooth gravy.`,ua:`Після смаження фрикадельок вмішайте борошно в жир на сковороді, додайте бульйон і вершки, уваріть до гладкої підливи.`,t:[`roux-making`],m:8,i:[[`all-purpose-flour`,30,`g`],[`beef-stock`,350,`ml`],[`heavy-cream`,100,`ml`]]},{en:`Cook lingonberries with sugar for a brief compote and serve alongside the meatballs, potatoes and cream gravy.`,ua:`Коротко проваріть брусницю з цукром до конфітюру й подайте поруч із фрикадельками, картоплею та вершковою підливою.`,t:[`sauteing`,`reducing-sauce`],m:8,i:[[`lingonberry`,140,`g`],[`white-granulated-sugar`,40,`g`]]}];var d={slug:o,id:t,country:`SE`,region:r,servings:4,minutes:44,title:s,text:g,steps:u};export{a as country,d as default,t as id,l as minutes,r as region,i as servings,o as slug,u as steps,g as text,s as title};